import pg from 'pg';
import { readFile, readdir } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { drizzle } from 'drizzle-orm/node-postgres';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import { readMigrationFiles, type MigrationMeta } from 'drizzle-orm/migrator';

const migrationsFolder = fileURLToPath(new URL('../drizzle/', import.meta.url));
const legacyFolder = fileURLToPath(new URL('../migrations/', import.meta.url));

// Applies schema changes generated by drizzle-kit. Databases created before
// Drizzle owned the schema still carry focus_schema_migrations; they finish any
// legacy files and then record the baseline as applied instead of running it.
export async function migrateDatabase(
  url = process.env.DATABASE_URL_UNPOOLED || process.env.DATABASE_URL,
) {
  if (!url)
    throw Error(
      'Set DATABASE_URL (and optionally DATABASE_URL_UNPOOLED) before migrating.',
    );
  const client = new pg.Client({
    connectionString: url,
    application_name: 'focus-migrations',
    connectionTimeoutMillis: 10000,
  });
  await client.connect();
  try {
    // A session lock spans the legacy step and Drizzle's own transaction; it
    // is released when the connection closes.
    await client.query("SELECT pg_advisory_lock(hashtext('focus-schema'))");
    const migrations = readMigrationFiles({ migrationsFolder });
    if (await exists(client, 'public.focus_schema_migrations'))
      await adoptLegacyDatabase(client, migrations[0]);
    await verifyApplied(client, migrations);
    await migrate(drizzle({ client }), { migrationsFolder });
  } finally {
    await client.end();
  }
}

async function exists(client: pg.Client, relation: string) {
  const { rows } = await client.query('SELECT to_regclass($1) AS oid', [
    relation,
  ]);
  return rows[0].oid !== null;
}

async function adoptLegacyDatabase(client: pg.Client, baseline: MigrationMeta) {
  await client.query('BEGIN');
  try {
    await applyLegacyMigrations(client);
    // Same ledger Drizzle's migrator creates, so it treats the baseline as done.
    await client.query('CREATE SCHEMA IF NOT EXISTS drizzle');
    await client.query(
      'CREATE TABLE IF NOT EXISTS drizzle.__drizzle_migrations (id SERIAL PRIMARY KEY, hash text NOT NULL, created_at bigint, name text, applied_at timestamp with time zone DEFAULT now())',
    );
    await client.query(
      'INSERT INTO drizzle.__drizzle_migrations (hash, created_at, name) SELECT $1, $2, $3 WHERE NOT EXISTS (SELECT 1 FROM drizzle.__drizzle_migrations WHERE name = $3)',
      [baseline.hash, baseline.folderMillis, baseline.name],
    );
    await client.query('COMMIT');
  } catch (e) {
    await client.query('ROLLBACK');
    throw e;
  }
}

async function applyLegacyMigrations(client: pg.Client) {
  for (const name of (await readdir(legacyFolder))
    .filter((n) => /^\d+_[a-z_]+\.sql$/.test(n))
    .sort()) {
    const sql = await readFile(legacyFolder + name, 'utf8'),
      checksum = createHash('sha256').update(sql).digest('hex');
    const old = (
      await client.query(
        'SELECT checksum FROM focus_schema_migrations WHERE name=$1',
        [name],
      )
    ).rows[0];
    if (old) {
      if (old.checksum !== checksum)
        throw Error('An applied migration was changed: ' + name);
      continue;
    }
    await client.query(sql);
    await client.query(
      'INSERT INTO focus_schema_migrations(name,checksum) VALUES($1,$2)',
      [name, checksum],
    );
  }
}

// Drizzle skips migrations by name, so an edited file would silently diverge
// from databases that already ran it.
async function verifyApplied(client: pg.Client, migrations: MigrationMeta[]) {
  if (!(await exists(client, 'drizzle.__drizzle_migrations'))) return;
  const files = new Map(migrations.map((m) => [m.name, m.hash]));
  const { rows } = await client.query<{ name: string; hash: string }>(
    'SELECT name, hash FROM drizzle.__drizzle_migrations',
  );
  for (const { name, hash } of rows)
    if (files.has(name) && files.get(name) !== hash)
      throw Error('An applied migration was changed: ' + name);
}
